import numpy as np,mujoco
from rcb_hb import Session

def setup():
 s=Session('window',instance='/app/instance.npz');m=s.model;d=s.data
 q=np.zeros(m.nu)
 for i in range(m.nu):
  if m.actuator_trntype[i]==0:q[i]=d.qpos[m.jnt_qposadr[m.actuator_trnid[i,0]]]
 return s,q

def norm(s,q):
 lo,hi=s.model.actuator_ctrlrange.T
 return np.clip(2*(q-lo)/(hi-lo)-1,-1,1)

def grip(q,prox=1.3,dist=2.5,thumb=1.):
 q=q.copy()
 for off in (0,20):
  q[np.array([29,32,35,39])+off]=prox
  q[np.array([30,33,36,40])+off]=dist
  q[23+off]=0.0;q[24+off]=thumb;q[25+off]=0.;q[26+off]=0.3;q[27+off]=1.3
 return q

def desc(s):
 d=s.data;m=s.model
 con=[]
